import{z as p,x as m,o,c as B,q as r,j as n,D as l,d as t,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"语言生成作为 MDP","description":"","frontmatter":{"title":"语言生成作为 MDP","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/llm-decision-view.md","filePath":"llm/llm-decision-view.md","lastUpdated":1791413859000}'),A={name:"llm/llm-decision-view.md"};function d(D,a,_,C,h,u){const E=m("Mermaid");return o(),B("div",null,[a[2]||(a[2]=r('<h1 id="语言生成作为-mdp" tabindex="-1">语言生成作为 MDP <a class="header-anchor" href="#语言生成作为-mdp" aria-label="Permalink to &quot;语言生成作为 MDP&quot;">​</a></h1><div class="epigraph"><p>自回归模型每选一个 token 就做了一次决策；整段生成是一个回合，环境从不掷骰子，唯一的随机源是策略自己。</p><footer>—— 据 MDP 框架（Bellman, Dynamic Programming, 1957；Sutton &amp; Barto 2018）对自回归生成的套用整理</footer></div><p><a href="/llm/value-policy-iteration">上一课</a>把「模型已知」的动态规划推到停止判据，也暴露了它的两个前提：状态可枚举、\\(P\\) 与 \\(r\\) 可逐状态查询。本课开新课序「语言模型的决策视角」，把语言生成逐项写成 MDP——状态、动作、回合、轨迹分布落位之后立刻看见：表格 DP 的两个前提全塌，课程由此推向无模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>前面各课——<a href="/llm/rlhf-pipeline">RLHF 流水线</a>、<a href="/llm/rlvr">RLVR</a>、<a href="/llm/prm-in-rl-loop">过程奖励进环</a>——一直在用「策略」「轨迹」「回合」，但没有一处把生成过程作为决策问题钉死：马尔可夫性从哪来、回合何时结束、第一课那个轨迹连乘在语言里剩几项。不写清楚这些，就分不清哪些 RL 结论原样适用、哪些因为生成问题的特殊结构而改变。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>逐项落位。<strong>状态</strong>：\\(s_t=(x, y_{\\lt t})\\)，prompt 加已生成前缀。<strong>动作</strong>：\\(a_t=y_t\\)，词表里的一个 token。<strong>转移</strong>：\\(s_{t+1}=s_t\\oplus y_t\\)，确定性拼接——教科书里环境掷骰子的那部分，在语言生成里是恒等映射。<strong>回合</strong>：采样到 EOS 或触发停止条件时结束（解码侧的终止机制见 <a href="/llm/stop-sequences">stop sequences</a>）；回合长 \\(T\\) 随机，可达数百上千 token。<strong>奖励</strong>：RLVR 里只在回合末由验证器给出 \\(R\\)，中间全零；过程奖励是把这笔账摊到中间步的尝试。<span class="marginnote">MDP（马尔可夫决策过程）翻译成大白话就是「下一步只看当前局面」的决策游戏：状态是此刻掌握的全部信息，动作是你能做的选择，奖励是事后结算的分数。这里把「局面」定义为 prompt 加已写出的字——每采一个 token，就是游戏走了一步。</span></p><p>代回第一课的连乘，转移因子 \\(P(s_{t+1}\\mid s_t,a_t)\\) 恒为 \\(1\\)，轨迹分布只剩策略：</p> \\[p^\\pi(\\tau)=\\rho(x)\\prod_{t=0}^{T-1}\\pi(y_t\\mid x,\\ y_{\\lt t}) \\]<p>\\(\\rho(x)\\) 是 prompt 分布。第一课「策略只通过动作分布进入」在这里走到极端：<strong>连乘里只剩策略项</strong>。优化目标 \\(J(\\pi)=\\mathbb{E}_{x\\sim\\rho,\\,y\\sim\\pi}[G_0]\\)，就是后训练实际在最大化的那个期望。</p>',10)),(o(),n(i,null,{default:l(()=>[s(E,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22prompt%20x%22%5D%20--%3E%20S1%5B%22%E7%8A%B6%E6%80%81%20s%20%3D%20(x%2C%20%E5%89%8D%E7%BC%80)%22%5D%0A%20%20S1%20--%3E%20A%5B%22%E5%8A%A8%E4%BD%9C%EF%BC%9A%E9%87%87%E4%B8%80%E4%B8%AA%20token%22%5D%0A%20%20A%20--%3E%20EOS%7B%22%E6%98%AF%20EOS%20%E6%88%96%E5%91%BD%E4%B8%AD%E5%81%9C%E6%AD%A2%3F%22%7D%0A%20%20EOS%20--%3E%7C%E5%90%A6%7C%20S2%5B%22%E6%8B%BC%E6%8E%A5%E8%BF%9B%E5%89%8D%E7%BC%80%EF%BC%8C%E5%9B%9E%E5%88%B0%E7%8A%B6%E6%80%81%22%5D%0A%20%20S2%20--%3E%20A%0A%20%20EOS%20--%3E%7C%E6%98%AF%7C%20R%5B%22%E9%AA%8C%E8%AF%81%E5%99%A8%E4%BB%98%20R%EF%BC%8C%E5%9B%9E%E5%90%88%E7%BB%93%E6%9D%9F%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[t("马尔可夫性免费成立：自回归的条件分布天然只看前缀，而状态"),e("strong",null,"定义"),t("就是「prompt + 全部历史」——第一课说状态压缩历史是建模负担，这里语言模型替你付了。也正因为如此，这颗 MDP 与教科书的最大差别是："),e("strong",null,"全部随机性来自策略"),t("。没有环境的转移噪声，意味着离策略修正只需修正动作项（后面重要性采样课的主题），也意味着「环境模型」在语言里只剩验证器那一环。")],-1)),a[5]||(a[5]=e("p",null,"但视角同时暴露维度灾难。词表 \\(10^5\\) 量级、生成上千步，前缀状态数上限约 \\(|V|^{T}\\approx 10^{5000}\\)——上一课表格 DP 的第一步「逐状态 backup」连一行都放不下；第二步「\\(r\\) 已知」也塌：\\(R\\) 由验证器在回合末给出，是黑箱函数不是可查询表。两个前提齐塌不是工程困难，是数学障碍，所以动态规划单元的算法在此让位。无模型方法——只从采样出的轨迹学习——成为唯一出路；但「从自己采的轨迹学」还藏着一个更早的前提：轨迹覆盖了哪些状态，价值就只能学到哪里。这是下一课的主题。",-1)),(o(),n(i,null,{default:l(()=>[s(E,{id:"mermaid-36",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22prompt%20x%22%5D%20--%3E%20RHO%5B%22%CF%81(x)%EF%BC%9A%E8%BF%9E%E4%B9%98%E7%9A%84%E7%AC%AC%E4%B8%80%E9%A1%B9%22%5D%0A%20%20RHO%20--%3E%20SEQ%5B%22%E6%AD%A4%E5%90%8E%E6%AF%8F%E6%AD%A5%EF%BC%9A%CF%80(y_t%20%7C%20x%2C%20y%3Ct)%22%5D%0A%20%20SEQ%20--%3E%20EOS%5B%22%E9%87%87%E5%88%B0%20EOS%EF%BC%8C%E8%BF%9E%E4%B9%98%E5%81%9C%E6%AD%A2%22%5D%0A%20%20ENV%5B%22%E7%8E%AF%E5%A2%83%E8%BD%AC%E7%A7%BB%20P(s%E2%80%B2%7Cs%2Ca)%22%5D%20--%3E%20ONE%5B%22%E6%81%92%E7%AD%89%E4%BA%8E%201%22%5D%0A%20%20ONE%20--%3E%20DROP%5B%22%E4%BB%8E%E8%BF%9E%E4%B9%98%E4%B8%AD%E6%B6%88%E5%A4%B1%22%5D%0A%20%20EOS%20--%3E%20PROD%5B%22%E8%BD%A8%E8%BF%B9%E6%A6%82%E7%8E%87%20%3D%20%CF%81(x)%20%C3%97%20%E5%90%84%E6%AD%A5%20%CF%80%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">\\(10^{5000}\\) 是什么概念：可观测宇宙的原子约 \\(10^{80}\\) 个。哪怕只生成 100 个 token、词表 10 万，候选句子也有 \\(10^{500}\\) 个——想给每种前缀留一行表格、逐个打分，存储先于计算崩溃。这就是「表格 DP 放不下」的直观尺寸。</span></p><p><span class="marginnote">转移为恒等也改变了 \\(\\gamma\\) 的含义：语言生成里 \\(\\gamma\\) 不再度量「环境延迟」，纯粹度量「多久之前的 token 还值得追究」——第一单元的有效视界读法在生成问题上是唯一活着的读法。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课的落位只覆盖单轮、无工具的生成：多轮对话与 agent 场景里，工具返回、检索结果、外部环境状态都得进状态定义，否则马尔可夫性被破坏——那是 agent 各课的事。不讲部分可观测；也不把「奖励只在回合末」当成问题结构的改变：奖励是观测不是状态，稀疏只让学习变难（第一课的结论原样适用）。<span class="marginnote">常见误区：把「奖励稀疏」理解成「没有奖励」。实际上每条轨迹收尾时都有一个确定的分数，只是中间每个 token 拿不到即时反馈——像整场考试只在交卷时给一个总分。难点是「这份总分该记到哪个字头上」（信用分配），而不是「有没有分可记」。</span></p><p>后课默认：生成 MDP 的状态是前缀、动作是 token、转移为恒等、轨迹分布只剩策略项。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>状态 = prompt + 前缀，动作 = token，回合 = EOS，转移是确定性拼接。</li><li>环境因子消失，轨迹分布 \\(p^\\pi(\\tau)=\\rho\\prod_t\\pi\\)：随机性全部来自策略。</li><li>马尔可夫性由自回归条件分布免费给出；奖励稀疏不影响它。</li><li>维度灾难 \\(|V|^T\\) 与验证器黑箱使表格 DP 两个前提齐塌，转向无模型。</li><li>无模型的前提是数据由策略采样产生，覆盖问题留给下一课。</li><li>出处：Bellman 1957；Sutton &amp; Barto 2018 第 3–4 章框架对自回归生成的套用。</li></ul>',7))])}const c=p(A,[["render",d]]);export{g as __pageData,c as default};
